import argparse
import importlib
import json
import sys
import webbrowser
from importlib.resources import files
from pathlib import Path

from .core import Challenge
from .runner import run_algorithm
from .simulation import PuzzleAlgorithm
from .validation import strict_loads, validate_trace


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(prog="daydokuthon")
    commands = parser.add_subparsers(dest="command", required=True)
    init = commands.add_parser("init", help="Create a participant algorithm starter")
    init.add_argument("--directory", type=Path, default=Path.cwd())
    run = commands.add_parser("run", help="Run YOUR local algorithm and record its actions")
    run.add_argument("--algorithm", required=True, help="module:ClassName")
    run.add_argument("--challenge", type=Path, required=True)
    run.add_argument("--output", type=Path, default=Path("submission.json"))
    for name in ("validate", "replay"):
        command = commands.add_parser(name)
        command.add_argument("trace", type=Path)
        command.add_argument("--challenge", type=Path, required=True)
        if name == "replay":
            command.add_argument("--port", type=int, default=8002)
            command.add_argument("--no-browser", action="store_true")
    serve = commands.add_parser("serve", help="Run the central challenge server")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8001)
    serve.add_argument("--database", type=Path, default=Path("daydokuthon.db"))
    args = parser.parse_args(argv)
    try:
        if args.command == "init":
            args.directory.mkdir(parents=True, exist_ok=True)
            destination = args.directory / "solution.py"
            with destination.open("x", encoding="utf-8") as output:
                output.write(files("daydokuthon").joinpath("starter.txt").read_text())
            print(f"Created {destination}. Download a challenge.json from your organizer.")
            return 0
        if args.command in ("run", "validate", "replay"):
            challenge = Challenge.from_dict(strict_loads(args.challenge.read_bytes()))
        if args.command == "run":
            # Import only explicitly selected LOCAL participant code. The central server
            # never uses this entry point or imports modules named in an uploaded trace.
            module_name, class_name = args.algorithm.split(":", 1)
            sys.path.insert(0, str(Path.cwd()))
            algorithm_type = getattr(importlib.import_module(module_name), class_name)
            if not isinstance(algorithm_type, type) or not issubclass(
                algorithm_type, PuzzleAlgorithm
            ):
                raise ValueError("Algorithm must be a PuzzleAlgorithm subclass")
            result = run_algorithm(algorithm_type(), challenge, args.output)
            print(json.dumps(result, indent=2))
            return 0 if result["solved"] and not result["error"] else 1
        if args.command == "validate":
            report = validate_trace(args.trace.read_bytes(), challenge)
            print(json.dumps(report.to_dict(), indent=2))
            return 0 if report.legal and report.solved else 1
        if args.command in ("serve", "replay"):
            try:
                import uvicorn

                from .server import Settings, create_app, create_replay_app
            except ImportError as error:
                raise ValueError(
                    'Install server features: pip install "daydokuthon[server]"'
                ) from error
            if args.command == "serve":
                settings = Settings.from_env(args.database)
                application = create_app(settings)
                host = args.host
            else:
                application = create_replay_app(challenge, args.trace.read_bytes())
                host = "127.0.0.1"
                if not args.no_browser:
                    import threading

                    threading.Timer(
                        1.5, lambda: webbrowser.open(f"http://127.0.0.1:{args.port}")
                    ).start()
            uvicorn.run(application, host=host, port=args.port)
            return 0
    except (ValueError, OSError, ImportError, AttributeError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
